PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?lightestHardware ?heaviestHardware WHERE {
  ?hardware a pv:Hardware ;
              pv:hasCategory ?category ;
              pv:weight_g ?weight .
  {
    SELECT ?category (MIN(?weight) AS ?minWeight) WHERE {
      ?hardware a pv:Hardware ;
                  pv:hasCategory ?category ;
                  pv:weight_g ?weight .
    } GROUP BY ?category
  }
  {
    SELECT ?category (MAX(?weight) AS ?maxWeight) WHERE {
      ?hardware a pv:Hardware ;
                  pv:hasCategory ?category ;
                  pv:weight_g ?weight .
    } GROUP BY ?category
  }
  FILTER(?weight = ?minWeight)
  ?lightestHardware a pv:Hardware ;
                    pv:hasCategory ?category ;
                    pv:weight_g ?minWeight .
  FILTER(?weight = ?maxWeight)
  ?heaviestHardware a pv:Hardware ;
                    pv:hasCategory ?category ;
                    pv:weight_g ?maxWeight .
} GROUP BY ?category ?lightestHardware ?heaviestHardware

